import os
import hashlib
import tempfile
import shutil
import unicodedata
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, abort
import secrets

app = Flask(__name__)

UPLOAD_BASE = '/var/uploads'
MAX_FILE_SIZE = 10 * 1024 * 1024
ALLOWED_EXTENSIONS = {'.png', '.jpg', '.jpeg', '.gif', '.pdf', '.txt'}

def _generate_storage_id():
    return secrets.token_hex(16)

def _sanitize_filename(filename):
    """Remove dangerous characters and normalize the filename."""
    # Strip leading/trailing whitespace
    cleaned = filename.strip()
    # Remove null bytes
    cleaned = cleaned.replace('\x00', '')
    # Collapse multiple dots
    while '..' in cleaned:
        cleaned = cleaned.replace('..', '.')
    # Remove path separators
    cleaned = cleaned.replace('/', '').replace('\\', '')
    return cleaned

def _validate_path_safety(filename):
    """Ensure filename doesn't escape upload directory."""
    # Check for path traversal attempts
    if '..' in filename:
        return False
    if filename.startswith('/'):
        return False
    if '\x00' in filename:
        return False
    # Verify the resolved path stays within bounds
    test_path = os.path.join(UPLOAD_BASE, filename)
    real_base = os.path.realpath(UPLOAD_BASE)
    real_path = os.path.realpath(test_path)
    if not real_path.startswith(real_base + os.sep):
        return False
    return True

def _check_extension(filename):
    """Validate file extension against allowlist."""
    _, ext = os.path.splitext(filename)
    return ext.lower() in ALLOWED_EXTENSIONS

def _compute_checksum(data):
    """Compute SHA-256 checksum of file data."""
    return hashlib.sha256(data).hexdigest()

def _normalize_for_storage(filename):
    """Normalize unicode characters for consistent storage."""
    # NFC normalization for consistent representation
    normalized = unicodedata.normalize('NFC', filename)
    return normalized

def _write_file_atomic(filepath, data):
    """Write file data with atomic rename pattern."""
    dir_path = os.path.dirname(filepath)
    os.makedirs(dir_path, exist_ok=True)
    tmp_fd, tmp_path = tempfile.mkstemp(dir=dir_path)
    try:
        os.write(tmp_fd, data)
        os.close(tmp_fd)
        shutil.move(tmp_path, filepath)
    except Exception:
        os.close(tmp_fd)
        os.unlink(tmp_path)
        raise

def _build_user_directory(user_id):
    """Construct per-user upload directory path."""
    safe_user = user_id.replace('/', '').replace('\\', '').replace('..', '')
    return os.path.join(UPLOAD_BASE, safe_user[:32])

@app.route('/upload', methods=['POST'])
def upload_file():
    """Handle file upload with validation."""
    user_id = request.headers.get('X-User-ID', '')
    if not user_id or len(user_id) > 64:
        abort(401)

    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if not uploaded.filename:
        return jsonify({'error': 'Empty filename'}), 400

    raw_filename = uploaded.filename

    # Step 1: Sanitize the raw filename
    sanitized = _sanitize_filename(raw_filename)

    # Step 2: Validate path safety on sanitized name
    if not _validate_path_safety(sanitized):
        return jsonify({'error': 'Invalid filename'}), 400

    # Step 3: Check extension
    if not _check_extension(sanitized):
        return jsonify({'error': 'File type not allowed'}), 400

    # Step 4: Read and validate file content
    file_data = uploaded.read()
    if len(file_data) > MAX_FILE_SIZE:
        return jsonify({'error': 'File too large'}), 400
    if len(file_data) == 0:
        return jsonify({'error': 'Empty file'}), 400

    # Step 5: Normalize filename for storage (handles unicode edge cases)
    storage_name = _normalize_for_storage(sanitized)

    # Step 6: Build final path and write
    user_dir = _build_user_directory(user_id)
    final_path = os.path.join(user_dir, storage_name)

    checksum = _compute_checksum(file_data)
    _write_file_atomic(final_path, file_data)

    return jsonify({
        'status': 'success',
        'filename': storage_name,
        'checksum': checksum,
        'size': len(file_data)
    }), 201

@app.route('/files/<user_id>', methods=['GET'])
def list_files(user_id):
    """List files for a user."""
    user_dir = _build_user_directory(user_id)
    if not os.path.isdir(user_dir):
        return jsonify({'files': []})
    files = []
    for f in os.listdir(user_dir):
        fpath = os.path.join(user_dir, f)
        if os.path.isfile(fpath):
            files.append({
                'name': f,
                'size': os.path.getsize(fpath)
            })
    return jsonify({'files': files})

@app.route('/download/<user_id>/<filename>', methods=['GET'])
def download_file(user_id, filename):
    """Download a specific file."""
    user_dir = _build_user_directory(user_id)
    sanitized = _sanitize_filename(filename)
    if not _validate_path_safety(sanitized):
        abort(403)
    filepath = os.path.join(user_dir, sanitized)
    real_base = os.path.realpath(user_dir)
    real_file = os.path.realpath(filepath)
    if not real_file.startswith(real_base + os.sep):
        abort(403)
    if not os.path.isfile(filepath):
        abort(404)
    with open(filepath, 'rb') as f:
        data = f.read()
    return data, 200, {'Content-Type': 'application/octet-stream'}

if __name__ == '__main__':
    os.makedirs(UPLOAD_BASE, exist_ok=True)
    app.run(host='127.0.0.1', port=8080)
